@startuml

class SensorController {
  + systemName : string
  + querySensorValues(inhabitantId : string) : string
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
  + isAdmin : boolean
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalPowerConsumption : float
}

class SensorValue {
  + value : float
  + timestamp : datetime
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email : string) : void
}

SensorController "1" *-- "1..*" Inhabitant : manages
SensorController "1" *-- "1" Apartment : monitors
Apartment "1" *-- "2..*" Room : contains
Room "1" *-- "1..*" Sensor : contains
Sensor "1" -- "1..*" SensorValue : records
Sensor "1" -- "0..1" SensorValue : lastValue
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
EMonitor ..> Sensor : checks
EMonitor ..> SensorController : sendsAlertVia
Inhabitant "1" -- "0..*" Sensor : configures

@enduml

